@block ArmIK begin
    # 1 kHz inverse kinematics of one stacked 7-DOF SRS arm holding the shared object (sampled
    # firmware). Generated by design/build_library.py; its Python twin is
    # `srs.ik_step(..., jac="analytic")` (design/srs.py).
    #
    # The damped least squares of the interactive page, one iteration per tick, warm-started
    # from the last solution (the page runs 8 iterations per animation frame):
    #
    #   e  = target - current (position [m]; orientation 0.5 rw sum c_i x t_i)
    #   y  = (J J^T + lam I)^-1 e                      task step
    #   z  = kn (home - q)                             pull toward home (shoulder yaw + s bias)
    #   v  = (J J^T + lamn I)^-1 J z                   its task-space part
    #   d  = z + J^T (y - v), scaled down as a whole so that max |d_k| <= dmax (a rate limit)
    #   q += d, then clamp to the joint limits
    #
    # Angles in degrees, J per degree (the page's units, so lam, lamn and kn are the page's
    # constants); J is the exact derivative of the page's error, where the page takes a 1 deg
    # finite difference. With the lock (obj[8] = 1) J5 stays at zero: 6 joints for 6
    # constraints, no null space, so the elbow bias does nothing. Two Cholesky factorisations
    # of the 6x6 J J^T solve the systems.
    #
    # The chain (page frame): the shoulder base at (s sx, sy0, 0); joint k turns the frame by
    # -q (pitch joints) or s q (the others) about its axis (x z y x y x z), then the frame moves
    # by off[k, :]. s = -1 mirrors the arm. `off` = the stacked offsets, or zero shoulder and
    # wrist offsets for the ideal SRS.
    @parameters begin
        s::Real = 1.0, [unit = "1", description = "Side: +1 the left arm (page +x), -1 the right arm (mirror)"]
        off::Mat{7,3} = [0.0 -0.06 0.025; 0.0 -0.06 -0.025; 0.0 -0.26 0.0; 0.0 -0.04 0.02; 0.0 -0.2 -0.02; 0.0 -0.04 0.02; 0.0 -0.09 0.0], [unit = "m", description = "Offset after each joint, in its own frame (row k: joint k)"]
        lo::Vec{7} = [-60.0, -20.0, -90.0, 0.0, -90.0, -60.0, -90.0], [description = "Lower joint limits"]
        hi::Vec{7} = [180.0, 120.0, 90.0, 140.0, 90.0, 60.0, 90.0], [description = "Upper joint limits"]
        home::Vec{7} = [25.0, 12.0, 0.0, 70.0, 0.0, 0.0, 0.0], [description = "Home posture of the null-space pull"]
        q0::Vec{7} = [25.0, 12.0, 0.0, 70.0, 0.0, 0.0, 0.0], [description = "Start posture (the IK warm start at the first tick)"]
        sx::Real = 0.2, [unit = "m", description = "Shoulder base at (s sx, sy0, 0)"]
        sy0::Real = 0.25, [unit = "m", description = "Shoulder base height"]
        hb::Real = 0.14, [unit = "m", description = "Grasp point: half the object length"]
        rw::Real = 0.3, [unit = "m", min = 1.0e-6, description = "Orientation weight (m per rad)"]
        lam::Real = 1e-05, [min = 0, description = "Damping of the task step (per-degree Jacobian)"]
        lamn::Real = 1e-09, [min = 0, description = "Damping of the null-space projection"]
        kn::Real = 0.1, [unit = "1", min = 0, description = "Null-space pull toward home per iteration"]
        dmax::Real = 0.05, [min = 0, description = "Largest joint step per tick in deg (the whole step is scaled down; 1 kHz: 50 deg/s)"]
    end
    @inputs obj::Vec{8}, [description = "Object (x, y, z [m], roll, pitch, yaw [deg]), elbow bias [deg], J5 lock"]
    @outputs begin
        qr1::Real = 0.4363323129985824, [unit = "rad", description = "Joint reference 1"]
        qr2::Real = 0.20943951023931956, [unit = "rad", description = "Joint reference 2"]
        qr3::Real = 0.0, [unit = "rad", description = "Joint reference 3"]
        qr4::Real = 1.2217304763960306, [unit = "rad", description = "Joint reference 4"]
        qr5::Real = 0.0, [unit = "rad", description = "Joint reference 5"]
        qr6::Real = 0.0, [unit = "rad", description = "Joint reference 6"]
        qr7::Real = 0.0, [unit = "rad", description = "Joint reference 7"]
        pe::Real = 0.0, [description = "Hand position error of the solution"]
        oe::Real = 0.0, [description = "Hand orientation error of the solution"]
        lim::Real = 100.0, [description = "Nearest joint limit (0: at a limit)"]
        limj::Real = 0.0, [unit = "1", description = "The joint of the nearest limit"]
        held::Real = 1.0, [unit = "1", description = "1 when the pose is held (under 2 mm and 2 deg)"]
        ex::Real = 0.0, [unit = "m", description = "Elbow (J4 origin) x, page frame"]
        ey::Real = 0.0, [unit = "m", description = "Elbow y, page frame"]
        ez::Real = 0.0, [unit = "m", description = "Elbow z, page frame"]
    end
    @variables begin
        q1::Real = 25.0, [description = "Joint 1 of the solution"]
        q2::Real = 12.0, [description = "Joint 2 of the solution"]
        q3::Real = 0.0, [description = "Joint 3 of the solution"]
        q4::Real = 70.0, [description = "Joint 4 of the solution"]
        q5::Real = 0.0, [description = "Joint 5 of the solution"]
        q6::Real = 0.0, [description = "Joint 6 of the solution"]
        q7::Real = 0.0, [description = "Joint 7 of the solution"]
        init::Real = 0.0, [unit = "1", description = "1 after the first tick"]
    end
    @discrete Ts = 0.001 begin
        # start: the configuration both variants hold (q0, the instance's start posture)
        if init < 0.5
            q1 = q0[1]
            q2 = q0[2]
            q3 = q0[3]
            q4 = q0[4]
            q5 = q0[5]
            q6 = q0[6]
            q7 = q0[7]
            init = 1.0
        end
        lockf = 0.0
        if obj[8] > 0.5
            lockf = 1.0
        end
        act5 = 1.0 - lockf
        q5 = act5 * q5
        # object rotation R = Ry(yaw) Rx(pitch) Rz(roll) (page frame) and the grasp target
        cr = cos(obj[4] * deg)
        sr = sin(obj[4] * deg)
        cp = cos(obj[5] * deg)
        sp = sin(obj[5] * deg)
        cy = cos(obj[6] * deg)
        sy = sin(obj[6] * deg)
        O_11 = cy * cr + sy * sp * sr
        O_12 = -cy * sr + sy * sp * cr
        O_13 = sy * cp
        O_21 = cp * sr
        O_22 = cp * cr
        O_23 = -sp
        O_31 = -sy * cr + cy * sp * sr
        O_32 = sy * sr + cy * sp * cr
        O_33 = cy * cp
        # hand target: at (s hb, 0, 0) of the object, columns R (0, s, 0), R (0, 0, -1), R (-s, 0, 0)
        tp1 = obj[1] + s * hb * O_11
        T1_1 = s * O_12
        T2_1 = -O_13
        T3_1 = -s * O_11
        tp2 = obj[2] + s * hb * O_21
        T1_2 = s * O_22
        T2_2 = -O_23
        T3_2 = -s * O_21
        tp3 = obj[3] + s * hb * O_31
        T1_3 = s * O_32
        T2_3 = -O_33
        T3_3 = -s * O_31
        # forward kinematics: joint origins o<k>, world axes u<k> (direction of +q), hand R7, p7
        R0_11 = 1.0
        R0_12 = 0.0
        R0_13 = 0.0
        R0_21 = 0.0
        R0_22 = 1.0
        R0_23 = 0.0
        R0_31 = 0.0
        R0_32 = 0.0
        R0_33 = 1.0
        p0_1 = s * sx
        p0_2 = sy0
        p0_3 = 0.0
        # J1 Shoulder pitch: about the page x, by -q
        o1_1 = p0_1
        u1_1 = -1.0 * R0_11
        o1_2 = p0_2
        u1_2 = -1.0 * R0_21
        o1_3 = p0_3
        u1_3 = -1.0 * R0_31
        c1 = cos(-1.0 * q1 * deg)
        s1 = sin(-1.0 * q1 * deg)
        R1_11 = R0_11
        R1_12 = c1 * R0_12 + s1 * R0_13
        R1_13 = c1 * R0_13 - s1 * R0_12
        R1_21 = R0_21
        R1_22 = c1 * R0_22 + s1 * R0_23
        R1_23 = c1 * R0_23 - s1 * R0_22
        R1_31 = R0_31
        R1_32 = c1 * R0_32 + s1 * R0_33
        R1_33 = c1 * R0_33 - s1 * R0_32
        p1_1 = p0_1 + R1_11 * off[1, 1] + R1_12 * off[1, 2] + R1_13 * off[1, 3]
        p1_2 = p0_2 + R1_21 * off[1, 1] + R1_22 * off[1, 2] + R1_23 * off[1, 3]
        p1_3 = p0_3 + R1_31 * off[1, 1] + R1_32 * off[1, 2] + R1_33 * off[1, 3]
        # J2 Shoulder roll: about the page z, by s q
        o2_1 = p1_1
        u2_1 = s * R1_13
        o2_2 = p1_2
        u2_2 = s * R1_23
        o2_3 = p1_3
        u2_3 = s * R1_33
        c2 = cos(s * q2 * deg)
        s2 = sin(s * q2 * deg)
        R2_11 = c2 * R1_11 + s2 * R1_12
        R2_12 = c2 * R1_12 - s2 * R1_11
        R2_13 = R1_13
        R2_21 = c2 * R1_21 + s2 * R1_22
        R2_22 = c2 * R1_22 - s2 * R1_21
        R2_23 = R1_23
        R2_31 = c2 * R1_31 + s2 * R1_32
        R2_32 = c2 * R1_32 - s2 * R1_31
        R2_33 = R1_33
        p2_1 = p1_1 + R2_11 * off[2, 1] + R2_12 * off[2, 2] + R2_13 * off[2, 3]
        p2_2 = p1_2 + R2_21 * off[2, 1] + R2_22 * off[2, 2] + R2_23 * off[2, 3]
        p2_3 = p1_3 + R2_31 * off[2, 1] + R2_32 * off[2, 2] + R2_33 * off[2, 3]
        # J3 Shoulder yaw: about the page y, by s q
        o3_1 = p2_1
        u3_1 = s * R2_12
        o3_2 = p2_2
        u3_2 = s * R2_22
        o3_3 = p2_3
        u3_3 = s * R2_32
        c3 = cos(s * q3 * deg)
        s3 = sin(s * q3 * deg)
        R3_11 = c3 * R2_11 - s3 * R2_13
        R3_12 = R2_12
        R3_13 = s3 * R2_11 + c3 * R2_13
        R3_21 = c3 * R2_21 - s3 * R2_23
        R3_22 = R2_22
        R3_23 = s3 * R2_21 + c3 * R2_23
        R3_31 = c3 * R2_31 - s3 * R2_33
        R3_32 = R2_32
        R3_33 = s3 * R2_31 + c3 * R2_33
        p3_1 = p2_1 + R3_11 * off[3, 1] + R3_12 * off[3, 2] + R3_13 * off[3, 3]
        p3_2 = p2_2 + R3_21 * off[3, 1] + R3_22 * off[3, 2] + R3_23 * off[3, 3]
        p3_3 = p2_3 + R3_31 * off[3, 1] + R3_32 * off[3, 2] + R3_33 * off[3, 3]
        # J4 Elbow pitch: about the page x, by -q
        o4_1 = p3_1
        u4_1 = -1.0 * R3_11
        o4_2 = p3_2
        u4_2 = -1.0 * R3_21
        o4_3 = p3_3
        u4_3 = -1.0 * R3_31
        c4 = cos(-1.0 * q4 * deg)
        s4 = sin(-1.0 * q4 * deg)
        R4_11 = R3_11
        R4_12 = c4 * R3_12 + s4 * R3_13
        R4_13 = c4 * R3_13 - s4 * R3_12
        R4_21 = R3_21
        R4_22 = c4 * R3_22 + s4 * R3_23
        R4_23 = c4 * R3_23 - s4 * R3_22
        R4_31 = R3_31
        R4_32 = c4 * R3_32 + s4 * R3_33
        R4_33 = c4 * R3_33 - s4 * R3_32
        p4_1 = p3_1 + R4_11 * off[4, 1] + R4_12 * off[4, 2] + R4_13 * off[4, 3]
        p4_2 = p3_2 + R4_21 * off[4, 1] + R4_22 * off[4, 2] + R4_23 * off[4, 3]
        p4_3 = p3_3 + R4_31 * off[4, 1] + R4_32 * off[4, 2] + R4_33 * off[4, 3]
        # J5 Forearm yaw: about the page y, by s q
        o5_1 = p4_1
        u5_1 = s * R4_12
        o5_2 = p4_2
        u5_2 = s * R4_22
        o5_3 = p4_3
        u5_3 = s * R4_32
        c5 = cos(s * q5 * deg)
        s5 = sin(s * q5 * deg)
        R5_11 = c5 * R4_11 - s5 * R4_13
        R5_12 = R4_12
        R5_13 = s5 * R4_11 + c5 * R4_13
        R5_21 = c5 * R4_21 - s5 * R4_23
        R5_22 = R4_22
        R5_23 = s5 * R4_21 + c5 * R4_23
        R5_31 = c5 * R4_31 - s5 * R4_33
        R5_32 = R4_32
        R5_33 = s5 * R4_31 + c5 * R4_33
        p5_1 = p4_1 + R5_11 * off[5, 1] + R5_12 * off[5, 2] + R5_13 * off[5, 3]
        p5_2 = p4_2 + R5_21 * off[5, 1] + R5_22 * off[5, 2] + R5_23 * off[5, 3]
        p5_3 = p4_3 + R5_31 * off[5, 1] + R5_32 * off[5, 2] + R5_33 * off[5, 3]
        # J6 Wrist pitch: about the page x, by -q
        o6_1 = p5_1
        u6_1 = -1.0 * R5_11
        o6_2 = p5_2
        u6_2 = -1.0 * R5_21
        o6_3 = p5_3
        u6_3 = -1.0 * R5_31
        c6 = cos(-1.0 * q6 * deg)
        s6 = sin(-1.0 * q6 * deg)
        R6_11 = R5_11
        R6_12 = c6 * R5_12 + s6 * R5_13
        R6_13 = c6 * R5_13 - s6 * R5_12
        R6_21 = R5_21
        R6_22 = c6 * R5_22 + s6 * R5_23
        R6_23 = c6 * R5_23 - s6 * R5_22
        R6_31 = R5_31
        R6_32 = c6 * R5_32 + s6 * R5_33
        R6_33 = c6 * R5_33 - s6 * R5_32
        p6_1 = p5_1 + R6_11 * off[6, 1] + R6_12 * off[6, 2] + R6_13 * off[6, 3]
        p6_2 = p5_2 + R6_21 * off[6, 1] + R6_22 * off[6, 2] + R6_23 * off[6, 3]
        p6_3 = p5_3 + R6_31 * off[6, 1] + R6_32 * off[6, 2] + R6_33 * off[6, 3]
        # J7 Wrist roll: about the page z, by s q
        o7_1 = p6_1
        u7_1 = s * R6_13
        o7_2 = p6_2
        u7_2 = s * R6_23
        o7_3 = p6_3
        u7_3 = s * R6_33
        c7 = cos(s * q7 * deg)
        s7 = sin(s * q7 * deg)
        R7_11 = c7 * R6_11 + s7 * R6_12
        R7_12 = c7 * R6_12 - s7 * R6_11
        R7_13 = R6_13
        R7_21 = c7 * R6_21 + s7 * R6_22
        R7_22 = c7 * R6_22 - s7 * R6_21
        R7_23 = R6_23
        R7_31 = c7 * R6_31 + s7 * R6_32
        R7_32 = c7 * R6_32 - s7 * R6_31
        R7_33 = R6_33
        p7_1 = p6_1 + R7_11 * off[7, 1] + R7_12 * off[7, 2] + R7_13 * off[7, 3]
        p7_2 = p6_2 + R7_21 * off[7, 1] + R7_22 * off[7, 2] + R7_23 * off[7, 3]
        p7_3 = p6_3 + R7_31 * off[7, 1] + R7_32 * off[7, 2] + R7_33 * off[7, 3]
        # error = target - current: position [m] and 0.5 rw sum c_i x t_i (the page's err)
        e1 = tp1 - p7_1
        e2 = tp2 - p7_2
        e3 = tp3 - p7_3
        e4 = 0.5 * rw * ((R7_21 * T1_3 - R7_31 * T1_2) + (R7_22 * T2_3 - R7_32 * T2_2) + (R7_23 * T3_3 - R7_33 * T3_2))
        e5 = 0.5 * rw * ((R7_31 * T1_1 - R7_11 * T1_3) + (R7_32 * T2_1 - R7_12 * T2_3) + (R7_33 * T3_1 - R7_13 * T3_3))
        e6 = 0.5 * rw * ((R7_11 * T1_2 - R7_21 * T1_1) + (R7_12 * T2_2 - R7_22 * T2_1) + (R7_13 * T3_2 - R7_23 * T3_1))
        # Jacobian d(current)/dq per degree (the exact derivative of -err), J5 column masked by the lock
        J1_1 = deg * (u1_2 * (p7_3 - o1_3) - u1_3 * (p7_2 - o1_2))
        J2_1 = deg * (u1_3 * (p7_1 - o1_1) - u1_1 * (p7_3 - o1_3))
        J3_1 = deg * (u1_1 * (p7_2 - o1_2) - u1_2 * (p7_1 - o1_1))
        g11_1 = (u1_2 * R7_31 - u1_3 * R7_21)
        g11_2 = (u1_3 * R7_11 - u1_1 * R7_31)
        g11_3 = (u1_1 * R7_21 - u1_2 * R7_11)
        g12_1 = (u1_2 * R7_32 - u1_3 * R7_22)
        g12_2 = (u1_3 * R7_12 - u1_1 * R7_32)
        g12_3 = (u1_1 * R7_22 - u1_2 * R7_12)
        g13_1 = (u1_2 * R7_33 - u1_3 * R7_23)
        g13_2 = (u1_3 * R7_13 - u1_1 * R7_33)
        g13_3 = (u1_1 * R7_23 - u1_2 * R7_13)
        J4_1 = -0.5 * rw * deg * ((g11_2 * T1_3 - g11_3 * T1_2) + (g12_2 * T2_3 - g12_3 * T2_2) + (g13_2 * T3_3 - g13_3 * T3_2))
        J5_1 = -0.5 * rw * deg * ((g11_3 * T1_1 - g11_1 * T1_3) + (g12_3 * T2_1 - g12_1 * T2_3) + (g13_3 * T3_1 - g13_1 * T3_3))
        J6_1 = -0.5 * rw * deg * ((g11_1 * T1_2 - g11_2 * T1_1) + (g12_1 * T2_2 - g12_2 * T2_1) + (g13_1 * T3_2 - g13_2 * T3_1))
        J1_2 = deg * (u2_2 * (p7_3 - o2_3) - u2_3 * (p7_2 - o2_2))
        J2_2 = deg * (u2_3 * (p7_1 - o2_1) - u2_1 * (p7_3 - o2_3))
        J3_2 = deg * (u2_1 * (p7_2 - o2_2) - u2_2 * (p7_1 - o2_1))
        g21_1 = (u2_2 * R7_31 - u2_3 * R7_21)
        g21_2 = (u2_3 * R7_11 - u2_1 * R7_31)
        g21_3 = (u2_1 * R7_21 - u2_2 * R7_11)
        g22_1 = (u2_2 * R7_32 - u2_3 * R7_22)
        g22_2 = (u2_3 * R7_12 - u2_1 * R7_32)
        g22_3 = (u2_1 * R7_22 - u2_2 * R7_12)
        g23_1 = (u2_2 * R7_33 - u2_3 * R7_23)
        g23_2 = (u2_3 * R7_13 - u2_1 * R7_33)
        g23_3 = (u2_1 * R7_23 - u2_2 * R7_13)
        J4_2 = -0.5 * rw * deg * ((g21_2 * T1_3 - g21_3 * T1_2) + (g22_2 * T2_3 - g22_3 * T2_2) + (g23_2 * T3_3 - g23_3 * T3_2))
        J5_2 = -0.5 * rw * deg * ((g21_3 * T1_1 - g21_1 * T1_3) + (g22_3 * T2_1 - g22_1 * T2_3) + (g23_3 * T3_1 - g23_1 * T3_3))
        J6_2 = -0.5 * rw * deg * ((g21_1 * T1_2 - g21_2 * T1_1) + (g22_1 * T2_2 - g22_2 * T2_1) + (g23_1 * T3_2 - g23_2 * T3_1))
        J1_3 = deg * (u3_2 * (p7_3 - o3_3) - u3_3 * (p7_2 - o3_2))
        J2_3 = deg * (u3_3 * (p7_1 - o3_1) - u3_1 * (p7_3 - o3_3))
        J3_3 = deg * (u3_1 * (p7_2 - o3_2) - u3_2 * (p7_1 - o3_1))
        g31_1 = (u3_2 * R7_31 - u3_3 * R7_21)
        g31_2 = (u3_3 * R7_11 - u3_1 * R7_31)
        g31_3 = (u3_1 * R7_21 - u3_2 * R7_11)
        g32_1 = (u3_2 * R7_32 - u3_3 * R7_22)
        g32_2 = (u3_3 * R7_12 - u3_1 * R7_32)
        g32_3 = (u3_1 * R7_22 - u3_2 * R7_12)
        g33_1 = (u3_2 * R7_33 - u3_3 * R7_23)
        g33_2 = (u3_3 * R7_13 - u3_1 * R7_33)
        g33_3 = (u3_1 * R7_23 - u3_2 * R7_13)
        J4_3 = -0.5 * rw * deg * ((g31_2 * T1_3 - g31_3 * T1_2) + (g32_2 * T2_3 - g32_3 * T2_2) + (g33_2 * T3_3 - g33_3 * T3_2))
        J5_3 = -0.5 * rw * deg * ((g31_3 * T1_1 - g31_1 * T1_3) + (g32_3 * T2_1 - g32_1 * T2_3) + (g33_3 * T3_1 - g33_1 * T3_3))
        J6_3 = -0.5 * rw * deg * ((g31_1 * T1_2 - g31_2 * T1_1) + (g32_1 * T2_2 - g32_2 * T2_1) + (g33_1 * T3_2 - g33_2 * T3_1))
        J1_4 = deg * (u4_2 * (p7_3 - o4_3) - u4_3 * (p7_2 - o4_2))
        J2_4 = deg * (u4_3 * (p7_1 - o4_1) - u4_1 * (p7_3 - o4_3))
        J3_4 = deg * (u4_1 * (p7_2 - o4_2) - u4_2 * (p7_1 - o4_1))
        g41_1 = (u4_2 * R7_31 - u4_3 * R7_21)
        g41_2 = (u4_3 * R7_11 - u4_1 * R7_31)
        g41_3 = (u4_1 * R7_21 - u4_2 * R7_11)
        g42_1 = (u4_2 * R7_32 - u4_3 * R7_22)
        g42_2 = (u4_3 * R7_12 - u4_1 * R7_32)
        g42_3 = (u4_1 * R7_22 - u4_2 * R7_12)
        g43_1 = (u4_2 * R7_33 - u4_3 * R7_23)
        g43_2 = (u4_3 * R7_13 - u4_1 * R7_33)
        g43_3 = (u4_1 * R7_23 - u4_2 * R7_13)
        J4_4 = -0.5 * rw * deg * ((g41_2 * T1_3 - g41_3 * T1_2) + (g42_2 * T2_3 - g42_3 * T2_2) + (g43_2 * T3_3 - g43_3 * T3_2))
        J5_4 = -0.5 * rw * deg * ((g41_3 * T1_1 - g41_1 * T1_3) + (g42_3 * T2_1 - g42_1 * T2_3) + (g43_3 * T3_1 - g43_1 * T3_3))
        J6_4 = -0.5 * rw * deg * ((g41_1 * T1_2 - g41_2 * T1_1) + (g42_1 * T2_2 - g42_2 * T2_1) + (g43_1 * T3_2 - g43_2 * T3_1))
        J1_5 = deg * (u5_2 * (p7_3 - o5_3) - u5_3 * (p7_2 - o5_2)) * act5
        J2_5 = deg * (u5_3 * (p7_1 - o5_1) - u5_1 * (p7_3 - o5_3)) * act5
        J3_5 = deg * (u5_1 * (p7_2 - o5_2) - u5_2 * (p7_1 - o5_1)) * act5
        g51_1 = (u5_2 * R7_31 - u5_3 * R7_21)
        g51_2 = (u5_3 * R7_11 - u5_1 * R7_31)
        g51_3 = (u5_1 * R7_21 - u5_2 * R7_11)
        g52_1 = (u5_2 * R7_32 - u5_3 * R7_22)
        g52_2 = (u5_3 * R7_12 - u5_1 * R7_32)
        g52_3 = (u5_1 * R7_22 - u5_2 * R7_12)
        g53_1 = (u5_2 * R7_33 - u5_3 * R7_23)
        g53_2 = (u5_3 * R7_13 - u5_1 * R7_33)
        g53_3 = (u5_1 * R7_23 - u5_2 * R7_13)
        J4_5 = -0.5 * rw * deg * ((g51_2 * T1_3 - g51_3 * T1_2) + (g52_2 * T2_3 - g52_3 * T2_2) + (g53_2 * T3_3 - g53_3 * T3_2)) * act5
        J5_5 = -0.5 * rw * deg * ((g51_3 * T1_1 - g51_1 * T1_3) + (g52_3 * T2_1 - g52_1 * T2_3) + (g53_3 * T3_1 - g53_1 * T3_3)) * act5
        J6_5 = -0.5 * rw * deg * ((g51_1 * T1_2 - g51_2 * T1_1) + (g52_1 * T2_2 - g52_2 * T2_1) + (g53_1 * T3_2 - g53_2 * T3_1)) * act5
        J1_6 = deg * (u6_2 * (p7_3 - o6_3) - u6_3 * (p7_2 - o6_2))
        J2_6 = deg * (u6_3 * (p7_1 - o6_1) - u6_1 * (p7_3 - o6_3))
        J3_6 = deg * (u6_1 * (p7_2 - o6_2) - u6_2 * (p7_1 - o6_1))
        g61_1 = (u6_2 * R7_31 - u6_3 * R7_21)
        g61_2 = (u6_3 * R7_11 - u6_1 * R7_31)
        g61_3 = (u6_1 * R7_21 - u6_2 * R7_11)
        g62_1 = (u6_2 * R7_32 - u6_3 * R7_22)
        g62_2 = (u6_3 * R7_12 - u6_1 * R7_32)
        g62_3 = (u6_1 * R7_22 - u6_2 * R7_12)
        g63_1 = (u6_2 * R7_33 - u6_3 * R7_23)
        g63_2 = (u6_3 * R7_13 - u6_1 * R7_33)
        g63_3 = (u6_1 * R7_23 - u6_2 * R7_13)
        J4_6 = -0.5 * rw * deg * ((g61_2 * T1_3 - g61_3 * T1_2) + (g62_2 * T2_3 - g62_3 * T2_2) + (g63_2 * T3_3 - g63_3 * T3_2))
        J5_6 = -0.5 * rw * deg * ((g61_3 * T1_1 - g61_1 * T1_3) + (g62_3 * T2_1 - g62_1 * T2_3) + (g63_3 * T3_1 - g63_1 * T3_3))
        J6_6 = -0.5 * rw * deg * ((g61_1 * T1_2 - g61_2 * T1_1) + (g62_1 * T2_2 - g62_2 * T2_1) + (g63_1 * T3_2 - g63_2 * T3_1))
        J1_7 = deg * (u7_2 * (p7_3 - o7_3) - u7_3 * (p7_2 - o7_2))
        J2_7 = deg * (u7_3 * (p7_1 - o7_1) - u7_1 * (p7_3 - o7_3))
        J3_7 = deg * (u7_1 * (p7_2 - o7_2) - u7_2 * (p7_1 - o7_1))
        g71_1 = (u7_2 * R7_31 - u7_3 * R7_21)
        g71_2 = (u7_3 * R7_11 - u7_1 * R7_31)
        g71_3 = (u7_1 * R7_21 - u7_2 * R7_11)
        g72_1 = (u7_2 * R7_32 - u7_3 * R7_22)
        g72_2 = (u7_3 * R7_12 - u7_1 * R7_32)
        g72_3 = (u7_1 * R7_22 - u7_2 * R7_12)
        g73_1 = (u7_2 * R7_33 - u7_3 * R7_23)
        g73_2 = (u7_3 * R7_13 - u7_1 * R7_33)
        g73_3 = (u7_1 * R7_23 - u7_2 * R7_13)
        J4_7 = -0.5 * rw * deg * ((g71_2 * T1_3 - g71_3 * T1_2) + (g72_2 * T2_3 - g72_3 * T2_2) + (g73_2 * T3_3 - g73_3 * T3_2))
        J5_7 = -0.5 * rw * deg * ((g71_3 * T1_1 - g71_1 * T1_3) + (g72_3 * T2_1 - g72_1 * T2_3) + (g73_3 * T3_1 - g73_1 * T3_3))
        J6_7 = -0.5 * rw * deg * ((g71_1 * T1_2 - g71_2 * T1_1) + (g72_1 * T2_2 - g72_2 * T2_1) + (g73_1 * T3_2 - g73_2 * T3_1))
        # A = J J^T (6x6, symmetric)
        A11 = J1_1 * J1_1 + J1_2 * J1_2 + J1_3 * J1_3 + J1_4 * J1_4 + J1_5 * J1_5 + J1_6 * J1_6 + J1_7 * J1_7
        A12 = J1_1 * J2_1 + J1_2 * J2_2 + J1_3 * J2_3 + J1_4 * J2_4 + J1_5 * J2_5 + J1_6 * J2_6 + J1_7 * J2_7
        A13 = J1_1 * J3_1 + J1_2 * J3_2 + J1_3 * J3_3 + J1_4 * J3_4 + J1_5 * J3_5 + J1_6 * J3_6 + J1_7 * J3_7
        A14 = J1_1 * J4_1 + J1_2 * J4_2 + J1_3 * J4_3 + J1_4 * J4_4 + J1_5 * J4_5 + J1_6 * J4_6 + J1_7 * J4_7
        A15 = J1_1 * J5_1 + J1_2 * J5_2 + J1_3 * J5_3 + J1_4 * J5_4 + J1_5 * J5_5 + J1_6 * J5_6 + J1_7 * J5_7
        A16 = J1_1 * J6_1 + J1_2 * J6_2 + J1_3 * J6_3 + J1_4 * J6_4 + J1_5 * J6_5 + J1_6 * J6_6 + J1_7 * J6_7
        A22 = J2_1 * J2_1 + J2_2 * J2_2 + J2_3 * J2_3 + J2_4 * J2_4 + J2_5 * J2_5 + J2_6 * J2_6 + J2_7 * J2_7
        A23 = J2_1 * J3_1 + J2_2 * J3_2 + J2_3 * J3_3 + J2_4 * J3_4 + J2_5 * J3_5 + J2_6 * J3_6 + J2_7 * J3_7
        A24 = J2_1 * J4_1 + J2_2 * J4_2 + J2_3 * J4_3 + J2_4 * J4_4 + J2_5 * J4_5 + J2_6 * J4_6 + J2_7 * J4_7
        A25 = J2_1 * J5_1 + J2_2 * J5_2 + J2_3 * J5_3 + J2_4 * J5_4 + J2_5 * J5_5 + J2_6 * J5_6 + J2_7 * J5_7
        A26 = J2_1 * J6_1 + J2_2 * J6_2 + J2_3 * J6_3 + J2_4 * J6_4 + J2_5 * J6_5 + J2_6 * J6_6 + J2_7 * J6_7
        A33 = J3_1 * J3_1 + J3_2 * J3_2 + J3_3 * J3_3 + J3_4 * J3_4 + J3_5 * J3_5 + J3_6 * J3_6 + J3_7 * J3_7
        A34 = J3_1 * J4_1 + J3_2 * J4_2 + J3_3 * J4_3 + J3_4 * J4_4 + J3_5 * J4_5 + J3_6 * J4_6 + J3_7 * J4_7
        A35 = J3_1 * J5_1 + J3_2 * J5_2 + J3_3 * J5_3 + J3_4 * J5_4 + J3_5 * J5_5 + J3_6 * J5_6 + J3_7 * J5_7
        A36 = J3_1 * J6_1 + J3_2 * J6_2 + J3_3 * J6_3 + J3_4 * J6_4 + J3_5 * J6_5 + J3_6 * J6_6 + J3_7 * J6_7
        A44 = J4_1 * J4_1 + J4_2 * J4_2 + J4_3 * J4_3 + J4_4 * J4_4 + J4_5 * J4_5 + J4_6 * J4_6 + J4_7 * J4_7
        A45 = J4_1 * J5_1 + J4_2 * J5_2 + J4_3 * J5_3 + J4_4 * J5_4 + J4_5 * J5_5 + J4_6 * J5_6 + J4_7 * J5_7
        A46 = J4_1 * J6_1 + J4_2 * J6_2 + J4_3 * J6_3 + J4_4 * J6_4 + J4_5 * J6_5 + J4_6 * J6_6 + J4_7 * J6_7
        A55 = J5_1 * J5_1 + J5_2 * J5_2 + J5_3 * J5_3 + J5_4 * J5_4 + J5_5 * J5_5 + J5_6 * J5_6 + J5_7 * J5_7
        A56 = J5_1 * J6_1 + J5_2 * J6_2 + J5_3 * J6_3 + J5_4 * J6_4 + J5_5 * J6_5 + J5_6 * J6_6 + J5_7 * J6_7
        A66 = J6_1 * J6_1 + J6_2 * J6_2 + J6_3 * J6_3 + J6_4 * J6_4 + J6_5 * J6_5 + J6_6 * J6_6 + J6_7 * J6_7
        # task step y = (A + lam I)^-1 e (Cholesky)
        La11 = sqrt(A11 + lam)
        La21 = (A12) / La11
        La31 = (A13) / La11
        La41 = (A14) / La11
        La51 = (A15) / La11
        La61 = (A16) / La11
        La22 = sqrt(A22 + lam - La21 * La21)
        La32 = (A23 - La31 * La21) / La22
        La42 = (A24 - La41 * La21) / La22
        La52 = (A25 - La51 * La21) / La22
        La62 = (A26 - La61 * La21) / La22
        La33 = sqrt(A33 + lam - La31 * La31 - La32 * La32)
        La43 = (A34 - La41 * La31 - La42 * La32) / La33
        La53 = (A35 - La51 * La31 - La52 * La32) / La33
        La63 = (A36 - La61 * La31 - La62 * La32) / La33
        La44 = sqrt(A44 + lam - La41 * La41 - La42 * La42 - La43 * La43)
        La54 = (A45 - La51 * La41 - La52 * La42 - La53 * La43) / La44
        La64 = (A46 - La61 * La41 - La62 * La42 - La63 * La43) / La44
        La55 = sqrt(A55 + lam - La51 * La51 - La52 * La52 - La53 * La53 - La54 * La54)
        La65 = (A56 - La61 * La51 - La62 * La52 - La63 * La53 - La64 * La54) / La55
        La66 = sqrt(A66 + lam - La61 * La61 - La62 * La62 - La63 * La63 - La64 * La64 - La65 * La65)
        wa1 = (e1) / La11
        wa2 = (e2 - La21 * wa1) / La22
        wa3 = (e3 - La31 * wa1 - La32 * wa2) / La33
        wa4 = (e4 - La41 * wa1 - La42 * wa2 - La43 * wa3) / La44
        wa5 = (e5 - La51 * wa1 - La52 * wa2 - La53 * wa3 - La54 * wa4) / La55
        wa6 = (e6 - La61 * wa1 - La62 * wa2 - La63 * wa3 - La64 * wa4 - La65 * wa5) / La66
        y6 = (wa6) / La66
        y5 = (wa5 - La65 * y6) / La55
        y4 = (wa4 - La54 * y5 - La64 * y6) / La44
        y3 = (wa3 - La43 * y4 - La53 * y5 - La63 * y6) / La33
        y2 = (wa2 - La32 * y3 - La42 * y4 - La52 * y5 - La62 * y6) / La22
        y1 = (wa1 - La21 * y2 - La31 * y3 - La41 * y4 - La51 * y5 - La61 * y6) / La11
        # null-space pull z toward home (the elbow bias moves the shoulder-yaw home, mirrored by s)
        z1 = kn * (home[1] - q1)
        z2 = kn * (home[2] - q2)
        z3 = kn * (home[3] + s * obj[7] - q3)
        z4 = kn * (home[4] - q4)
        z5 = act5 * kn * (home[5] - q5)
        z6 = kn * (home[6] - q6)
        z7 = kn * (home[7] - q7)
        b1 = J1_1 * z1 + J1_2 * z2 + J1_3 * z3 + J1_4 * z4 + J1_5 * z5 + J1_6 * z6 + J1_7 * z7
        b2 = J2_1 * z1 + J2_2 * z2 + J2_3 * z3 + J2_4 * z4 + J2_5 * z5 + J2_6 * z6 + J2_7 * z7
        b3 = J3_1 * z1 + J3_2 * z2 + J3_3 * z3 + J3_4 * z4 + J3_5 * z5 + J3_6 * z6 + J3_7 * z7
        b4 = J4_1 * z1 + J4_2 * z2 + J4_3 * z3 + J4_4 * z4 + J4_5 * z5 + J4_6 * z6 + J4_7 * z7
        b5 = J5_1 * z1 + J5_2 * z2 + J5_3 * z3 + J5_4 * z4 + J5_5 * z5 + J5_6 * z6 + J5_7 * z7
        b6 = J6_1 * z1 + J6_2 * z2 + J6_3 * z3 + J6_4 * z4 + J6_5 * z5 + J6_6 * z6 + J6_7 * z7
        # its task-space part u = (A + lamn I)^-1 J z, removed so the pull acts in the null space
        Lb11 = sqrt(A11 + lamn)
        Lb21 = (A12) / Lb11
        Lb31 = (A13) / Lb11
        Lb41 = (A14) / Lb11
        Lb51 = (A15) / Lb11
        Lb61 = (A16) / Lb11
        Lb22 = sqrt(A22 + lamn - Lb21 * Lb21)
        Lb32 = (A23 - Lb31 * Lb21) / Lb22
        Lb42 = (A24 - Lb41 * Lb21) / Lb22
        Lb52 = (A25 - Lb51 * Lb21) / Lb22
        Lb62 = (A26 - Lb61 * Lb21) / Lb22
        Lb33 = sqrt(A33 + lamn - Lb31 * Lb31 - Lb32 * Lb32)
        Lb43 = (A34 - Lb41 * Lb31 - Lb42 * Lb32) / Lb33
        Lb53 = (A35 - Lb51 * Lb31 - Lb52 * Lb32) / Lb33
        Lb63 = (A36 - Lb61 * Lb31 - Lb62 * Lb32) / Lb33
        Lb44 = sqrt(A44 + lamn - Lb41 * Lb41 - Lb42 * Lb42 - Lb43 * Lb43)
        Lb54 = (A45 - Lb51 * Lb41 - Lb52 * Lb42 - Lb53 * Lb43) / Lb44
        Lb64 = (A46 - Lb61 * Lb41 - Lb62 * Lb42 - Lb63 * Lb43) / Lb44
        Lb55 = sqrt(A55 + lamn - Lb51 * Lb51 - Lb52 * Lb52 - Lb53 * Lb53 - Lb54 * Lb54)
        Lb65 = (A56 - Lb61 * Lb51 - Lb62 * Lb52 - Lb63 * Lb53 - Lb64 * Lb54) / Lb55
        Lb66 = sqrt(A66 + lamn - Lb61 * Lb61 - Lb62 * Lb62 - Lb63 * Lb63 - Lb64 * Lb64 - Lb65 * Lb65)
        wb1 = (b1) / Lb11
        wb2 = (b2 - Lb21 * wb1) / Lb22
        wb3 = (b3 - Lb31 * wb1 - Lb32 * wb2) / Lb33
        wb4 = (b4 - Lb41 * wb1 - Lb42 * wb2 - Lb43 * wb3) / Lb44
        wb5 = (b5 - Lb51 * wb1 - Lb52 * wb2 - Lb53 * wb3 - Lb54 * wb4) / Lb55
        wb6 = (b6 - Lb61 * wb1 - Lb62 * wb2 - Lb63 * wb3 - Lb64 * wb4 - Lb65 * wb5) / Lb66
        v6 = (wb6) / Lb66
        v5 = (wb5 - Lb65 * v6) / Lb55
        v4 = (wb4 - Lb54 * v5 - Lb64 * v6) / Lb44
        v3 = (wb3 - Lb43 * v4 - Lb53 * v5 - Lb63 * v6) / Lb33
        v2 = (wb2 - Lb32 * v3 - Lb42 * v4 - Lb52 * v5 - Lb62 * v6) / Lb22
        v1 = (wb1 - Lb21 * v2 - Lb31 * v3 - Lb41 * v4 - Lb51 * v5 - Lb61 * v6) / Lb11
        # step d = z + J^T (y - u), scaled as a whole to at most dmax per joint and tick (a rate
        # limit that keeps the step's direction, so a fast self-motion stays in the null space);
        # the joints stay inside their limits
        d1 = z1 + J1_1 * (y1 - v1) + J2_1 * (y2 - v2) + J3_1 * (y3 - v3) + J4_1 * (y4 - v4) + J5_1 * (y5 - v5) + J6_1 * (y6 - v6)
        d2 = z2 + J1_2 * (y1 - v1) + J2_2 * (y2 - v2) + J3_2 * (y3 - v3) + J4_2 * (y4 - v4) + J5_2 * (y5 - v5) + J6_2 * (y6 - v6)
        d3 = z3 + J1_3 * (y1 - v1) + J2_3 * (y2 - v2) + J3_3 * (y3 - v3) + J4_3 * (y4 - v4) + J5_3 * (y5 - v5) + J6_3 * (y6 - v6)
        d4 = z4 + J1_4 * (y1 - v1) + J2_4 * (y2 - v2) + J3_4 * (y3 - v3) + J4_4 * (y4 - v4) + J5_4 * (y5 - v5) + J6_4 * (y6 - v6)
        d5 = z5 + J1_5 * (y1 - v1) + J2_5 * (y2 - v2) + J3_5 * (y3 - v3) + J4_5 * (y4 - v4) + J5_5 * (y5 - v5) + J6_5 * (y6 - v6)
        d6 = z6 + J1_6 * (y1 - v1) + J2_6 * (y2 - v2) + J3_6 * (y3 - v3) + J4_6 * (y4 - v4) + J5_6 * (y5 - v5) + J6_6 * (y6 - v6)
        d7 = z7 + J1_7 * (y1 - v1) + J2_7 * (y2 - v2) + J3_7 * (y3 - v3) + J4_7 * (y4 - v4) + J5_7 * (y5 - v5) + J6_7 * (y6 - v6)
        dm = max(max(max(abs(d1), abs(d2)), max(abs(d3), abs(d4))), max(max(abs(d5), abs(d6)), abs(d7)))
        sc = 1.0
        if dm > dmax
            sc = dmax / dm
        end
        q1 = clamp(q1 + sc * d1, lo[1], hi[1])
        q2 = clamp(q2 + sc * d2, lo[2], hi[2])
        q3 = clamp(q3 + sc * d3, lo[3], hi[3])
        q4 = clamp(q4 + sc * d4, lo[4], hi[4])
        q5 = clamp(q5 + sc * d5, lo[5], hi[5])
        q6 = clamp(q6 + sc * d6, lo[6], hi[6])
        q7 = clamp(q7 + sc * d7, lo[7], hi[7])
        q5 = act5 * q5
        qr1 = q1 * deg
        qr2 = q2 * deg
        qr3 = q3 * deg
        qr4 = q4 * deg
        qr5 = q5 * deg
        qr6 = q6 * deg
        qr7 = q7 * deg
        # readouts of the pose this tick started from (the page's: mm, deg, nearest limit in %)
        pe = 1000.0 * sqrt(e1 * e1 + e2 * e2 + e3 * e3)
        oe = asin(min(1.0, sqrt(e4 * e4 + e5 * e5 + e6 * e6) / rw)) / deg
        m = 1.0
        mj = 0.0
        f1 = min(q1 - lo[1], hi[1] - q1) / (hi[1] - lo[1])
        if f1 < m
            m = f1
            mj = 1.0
        end
        f2 = min(q2 - lo[2], hi[2] - q2) / (hi[2] - lo[2])
        if f2 < m
            m = f2
            mj = 2.0
        end
        f3 = min(q3 - lo[3], hi[3] - q3) / (hi[3] - lo[3])
        if f3 < m
            m = f3
            mj = 3.0
        end
        f4 = min(q4 - lo[4], hi[4] - q4) / (hi[4] - lo[4])
        if f4 < m
            m = f4
            mj = 4.0
        end
        f5 = min(q5 - lo[5], hi[5] - q5) / (hi[5] - lo[5])
        if f5 < m && lockf < 0.5
            m = f5
            mj = 5.0
        end
        f6 = min(q6 - lo[6], hi[6] - q6) / (hi[6] - lo[6])
        if f6 < m
            m = f6
            mj = 6.0
        end
        f7 = min(q7 - lo[7], hi[7] - q7) / (hi[7] - lo[7])
        if f7 < m
            m = f7
            mj = 7.0
        end
        ex = o4_1
        ey = o4_2
        ez = o4_3
        lim = 100.0 * m
        limj = mj
        held = 0.0
        if pe < 2.0 && oe < 2.0
            held = 1.0
        end
    end
end
